import{bQ as e,aL as l,u as a,G as n}from"./chunks/framework.DjMJXVsR.js";const u=JSON.parse('{"title":"AI 智能体造词运动：一场精心设计的概念泡沫","description":"","frontmatter":{"title":"AI 智能体造词运动：一场精心设计的概念泡沫","date":"2026-06-18T00:00:00.000Z","categories":["AI"],"tags":["AI","Agent"]},"headers":[],"relativePath":"posts/AI/ai-agent-bubble.md","filePath":"posts/AI/ai-agent-bubble.md"}'),i={name:"posts/AI/ai-agent-bubble.md"};function o(s,t,r,d,g,h){return l(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="ai-智能体造词运动-一场精心设计的概念泡沫" tabindex="-1">AI 智能体造词运动：一场精心设计的概念泡沫 <a class="header-anchor" href="#ai-智能体造词运动-一场精心设计的概念泡沫" aria-label="Permalink to &quot;AI 智能体造词运动：一场精心设计的概念泡沫&quot;">​</a></h1><h2 id="一、现象-每三个月一个新词" tabindex="-1">一、现象：每三个月一个新词 <a class="header-anchor" href="#一、现象-每三个月一个新词" aria-label="Permalink to &quot;一、现象：每三个月一个新词&quot;">​</a></h2><p>如果你过去两年持续关注 AI 圈，会发现一个规律：<strong>每过三个月，就会出现一个你必须学会的新词，否则就会被行业&quot;淘汰&quot;</strong>。</p><table tabindex="0"><thead><tr><th style="text-align:left;">时间</th><th style="text-align:left;">热词</th><th style="text-align:left;">当时的话术</th><th style="text-align:left;">现在的状态</th></tr></thead><tbody><tr><td style="text-align:left;">2023 Q1</td><td style="text-align:left;">Prompt Engineering</td><td style="text-align:left;">&quot;不会写 Prompt = 不会用 AI&quot;</td><td style="text-align:left;">已被内化为基础技能，独立岗位消失</td></tr><tr><td style="text-align:left;">2023 Q4</td><td style="text-align:left;">RAG</td><td style="text-align:left;">&quot;向量数据库是 AI 时代的 MySQL&quot;</td><td style="text-align:left;">工程化落地，成为基础设施的一环</td></tr><tr><td style="text-align:left;">2024 Q2</td><td style="text-align:left;">CoT / ReAct / ToT</td><td style="text-align:left;">&quot;思维链让模型会思考&quot;</td><td style="text-align:left;">已被训练进模型，默认触发</td></tr><tr><td style="text-align:left;">2024 Q4</td><td style="text-align:left;">Agent</td><td style="text-align:left;">&quot;AI 的终极形态是自主智能体&quot;</td><td style="text-align:left;">大规模概念炒作期</td></tr><tr><td style="text-align:left;">2025 Q2</td><td style="text-align:left;">Context Engineering</td><td style="text-align:left;">&quot;Prompt 已死，上下文工程才是未来&quot;</td><td style="text-align:left;">被 Harness Engineering 吞并</td></tr><tr><td style="text-align:left;">2025 Q4</td><td style="text-align:left;">MCP</td><td style="text-align:left;">&quot;AI 时代的 USB-C 接口标准&quot;</td><td style="text-align:left;">协议层基础设施，不再被单独讨论</td></tr><tr><td style="text-align:left;">2026 Q1</td><td style="text-align:left;">Harness Engineering</td><td style="text-align:left;">&quot;给 Agent 搭脚手架才是核心壁垒&quot;</td><td style="text-align:left;">迅速过气</td></tr><tr><td style="text-align:left;">2026 Q2</td><td style="text-align:left;">Loop Engineering</td><td style="text-align:left;">&quot;设计自循环才是下一代 AI 工程&quot;</td><td style="text-align:left;">正在膨胀的顶点</td></tr></tbody></table><p>这种造词速度，已经超过了中国互联网的&quot;风口制造机&quot;。问题是：<strong>这些概念背后，真的有什么本质性的技术突破吗？</strong></p><hr><h2 id="二、拆穿-每一个新词都是老活新整" tabindex="-1">二、拆穿：每一个新词都是老活新整 <a class="header-anchor" href="#二、拆穿-每一个新词都是老活新整" aria-label="Permalink to &quot;二、拆穿：每一个新词都是老活新整&quot;">​</a></h2><h3 id="_2-1-agent-的本质" tabindex="-1">2.1 Agent 的本质 <a class="header-anchor" href="#_2-1-agent-的本质" aria-label="Permalink to &quot;2.1 Agent 的本质&quot;">​</a></h3><p>外界对 Agent 的想象：</p><blockquote><p>&quot;它能思考、学习、进化，甚至可能产生意识……&quot;</p></blockquote><p>Agent 的实际代码：</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> not</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> done:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    thought </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> llm.think(context)      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 预测下一个 token</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    action </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pick_action(thought)     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 调用预定义工具</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    observation </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> tool.execute(action) </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 拿结果</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    context </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">+=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> observation            </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 拼接字符串更新上下文</span></span></code></pre></div><p>一个 <code>while</code> 循环 + 一个 LLM + 一堆 API 调用。</p><p>OpenClaw 创始人 Peter Steinberger 在被问到&quot;这不就是定时任务吗&quot;时，回答得很直白：</p><blockquote><p><strong>&quot;对，说到底就是定时任务。整个项目就是把几个依赖项粘合在一起，没有什么惊天原创，就像 Dropbox 本质也只是多了几步的 FTP。&quot;</strong></p></blockquote><p>这不是谦虚，这是诚实。</p><h3 id="_2-2-prompt-→-context-→-harness-→-loop-的套娃" tabindex="-1">2.2 Prompt → Context → Harness → Loop 的套娃 <a class="header-anchor" href="#_2-2-prompt-→-context-→-harness-→-loop-的套娃" aria-label="Permalink to &quot;2.2 Prompt → Context → Harness → Loop 的套娃&quot;">​</a></h3><p>把这四个&quot;工程范式&quot;并排对比，你会发现一个尴尬的事实：</p><table tabindex="0"><thead><tr><th style="text-align:left;">范式</th><th style="text-align:left;">宣称的核心</th><th style="text-align:left;">实际做了什么</th><th style="text-align:left;">本质上</th></tr></thead><tbody><tr><td style="text-align:left;">Prompt Engineering</td><td style="text-align:left;">写好提示词</td><td style="text-align:left;">给模型输入文本</td><td style="text-align:left;"><strong>写好函数的入参</strong></td></tr><tr><td style="text-align:left;">Context Engineering</td><td style="text-align:left;">喂够上下文</td><td style="text-align:left;">把更多文本塞进窗口</td><td style="text-align:left;"><strong>把入参变长、变结构化</strong></td></tr><tr><td style="text-align:left;">Harness Engineering</td><td style="text-align:left;">搭执行环境</td><td style="text-align:left;">给模型注册工具、加权限</td><td style="text-align:left;"><strong>给函数配外部依赖</strong></td></tr><tr><td style="text-align:left;">Loop Engineering</td><td style="text-align:left;">设计自循环</td><td style="text-align:left;">用 while 循环反复调用</td><td style="text-align:left;"><strong>把函数放进一个循环里</strong></td></tr></tbody></table><p>四者不是&quot;范式跃迁&quot;，而是<strong>同一套自动化脚本的不同抽象层级</strong>。就像你不可能说&quot;从写函数到写循环是编程范式的革命&quot;。</p><h3 id="_2-3-mcp-的本质" tabindex="-1">2.3 MCP 的本质 <a class="header-anchor" href="#_2-3-mcp-的本质" aria-label="Permalink to &quot;2.3 MCP 的本质&quot;">​</a></h3><p>MCP（Model Context Protocol）被包装成&quot;AI 时代的 USB-C&quot;。</p><p>实际呢？它是一个<strong>JSON-RPC 接口标准</strong>，规定了 LLM 如何调用外部工具。类似的东西在软件工程里存在了几十年：gRPC、REST、SOAP、CORBA……</p><p>把接口标准重新命名为&quot;协议&quot;，再套上&quot;AI 原生&quot;的外衣，估值就能翻十倍。这是概念炼金术，不是技术创新。</p><h3 id="_2-4-自主决策-的真相" tabindex="-1">2.4 &quot;自主决策&quot;的真相 <a class="header-anchor" href="#_2-4-自主决策-的真相" aria-label="Permalink to &quot;2.4 &quot;自主决策&quot;的真相&quot;">​</a></h3><p>很多 Agent 产品宣传的&quot;自主决策&quot;，拆解开来：</p><ul><li>判断用哪个工具 → 其实是<strong>硬编码的规则匹配</strong>或<strong>简单的关键词路由</strong></li><li>决定下一步做什么 → 其实是<strong>预定义的状态机</strong></li><li>自我修正 → 其实是<strong>把错误信息拼进下一次 Prompt</strong></li></ul><p>一旦遇到稍微复杂、边界模糊的场景，这些&quot;自主决策&quot;就会原形毕露。</p><hr><h2 id="三、谁在给泡沫充气" tabindex="-1">三、谁在给泡沫充气 <a class="header-anchor" href="#三、谁在给泡沫充气" aria-label="Permalink to &quot;三、谁在给泡沫充气&quot;">​</a></h2><h3 id="_3-1-资本需要新故事" tabindex="-1">3.1 资本需要新故事 <a class="header-anchor" href="#_3-1-资本需要新故事" aria-label="Permalink to &quot;3.1 资本需要新故事&quot;">​</a></h3><p>2024 年，全球 AI Agent 融资总额超过 87 亿美元。但同期有 <strong>62% 的项目连最基本的产品 Demo 都没推向市场</strong>。</p><p>一个估值 30 亿的明星项目，内测用户反馈&quot;自动发邮件功能老是出毛病&quot;，团队却忙着发公关稿宣扬&quot;行业颠覆性&quot;。</p><p>资本不会反复投资同一个故事。Prompt Engineering 讲完了，必须讲 Context；Context 讲完了，必须讲 Agent；Agent 讲完了，必须讲 Loop。<strong>叙事不能停，一停估值就崩</strong>。</p><h3 id="_3-2-创业公司需要护城河幻觉" tabindex="-1">3.2 创业公司需要护城河幻觉 <a class="header-anchor" href="#_3-2-创业公司需要护城河幻觉" aria-label="Permalink to &quot;3.2 创业公司需要护城河幻觉&quot;">​</a></h3><p>大模型能力是巨头垄断的，创业公司很难在底层竞争。那怎么办？</p><p>造概念。</p><p>&quot;我们不做模型，我们做 Context Engineering 的基础设施&quot;——这句话翻译过来就是：&quot;我们在巨头的 API 外面包了一层，希望能多收点钱。&quot;</p><p>很多拿到融资的 Agent 创业公司，核心代码量不超过 5000 行，70% 的工作量是在写 PPT 和发推特。</p><h3 id="_3-3-自媒体需要流量" tabindex="-1">3.3 自媒体需要流量 <a class="header-anchor" href="#_3-3-自媒体需要流量" aria-label="Permalink to &quot;3.3 自媒体需要流量&quot;">​</a></h3><p>技术圈有个黑色幽默：</p><blockquote><p>一篇论证&quot;Prompt Engineering 已死&quot;的文章，是用三轮精心迭代的 Prompt 写出来的。</p></blockquote><p>这是自我证否的套娃。自媒体需要不断制造&quot;旧概念已死、新概念当立&quot;的焦虑，才能维持流量。读者越焦虑，点击量越高。</p><hr><h2 id="四、gartner-曲线不会骗人" tabindex="-1">四、Gartner 曲线不会骗人 <a class="header-anchor" href="#四、gartner-曲线不会骗人" aria-label="Permalink to &quot;四、Gartner 曲线不会骗人&quot;">​</a></h2><p>Gartner 2024-2025 年的技术成熟度曲线给出了一个清晰的定位：</p><p><strong>Agentic AI（自主性 AI）正处于&quot;期望膨胀顶峰（Peak of Inflated Expectations）&quot;的前夜。</strong></p><p>这意味着什么？</p><table tabindex="0"><thead><tr><th style="text-align:left;">阶段</th><th style="text-align:left;">特征</th><th style="text-align:left;">当前 Agent 圈的状态</th></tr></thead><tbody><tr><td style="text-align:left;">技术萌芽期</td><td style="text-align:left;">概念提出，少数早期采用者</td><td style="text-align:left;">2023-2024，已过去</td></tr><tr><td style="text-align:left;"><strong>期望膨胀期</strong></td><td style="text-align:left;"><strong>媒体炒作、资本涌入、过度承诺</strong></td><td style="text-align:left;"><strong>我们现在在这里</strong></td></tr><tr><td style="text-align:left;">泡沫破裂期</td><td style="text-align:left;">幻觉暴露、成本现实、Demo 与产品鸿沟</td><td style="text-align:left;">即将到来</td></tr><tr><td style="text-align:left;">失望低谷期</td><td style="text-align:left;">&quot;Agent 已死&quot;论、回归传统开发</td><td style="text-align:left;">大概率 2027 年</td></tr><tr><td style="text-align:left;">稳步爬坡期</td><td style="text-align:left;">工程化落地、垂直场景深耕</td><td style="text-align:left;">2028 年以后</td></tr><tr><td style="text-align:left;">生产成熟期</td><td style="text-align:left;">成为基础设施的一部分</td><td style="text-align:left;">远期</td></tr></tbody></table><p>17 只 AI 智能体概念股中，已有 10 只从年内高点回撤超过 20%。<strong>股价比论文先一步说出了真相</strong>。</p><hr><h2 id="五、最讽刺的自我证伪" tabindex="-1">五、最讽刺的自我证伪 <a class="header-anchor" href="#五、最讽刺的自我证伪" aria-label="Permalink to &quot;五、最讽刺的自我证伪&quot;">​</a></h2><p>AI 圈流传最广的一个悖论：</p><blockquote><p>&quot;2026 年，Prompt Engineering 已经死了。&quot;——这句话本身是用精心设计的 Prompt 写出来的。</p></blockquote><p>更深层的问题是：<strong>当模型足够强、系统足够智能，人类剩下的那部分判断力——定义&#39;什么是好的输出&#39;——还能维持多久？</strong></p><p>如果 Loop Engineering 真的成立，那么设计 Loop 的人，是不是也在给自己写墓志铭？</p><p>下一个被宣布&quot;死亡&quot;的，会不会就是 Loop Engineering 本身？</p><hr><h2 id="六、什么才是真正有价值的" tabindex="-1">六、什么才是真正有价值的 <a class="header-anchor" href="#六、什么才是真正有价值的" aria-label="Permalink to &quot;六、什么才是真正有价值的&quot;">​</a></h2><p>拆穿泡沫，不是为了否定一切。Agent 方向确实有真实价值，但它藏在喧嚣之下：</p><table tabindex="0"><thead><tr><th style="text-align:left;">泡沫叙事</th><th style="text-align:left;">真实价值</th></tr></thead><tbody><tr><td style="text-align:left;">&quot;通用 Agent 能做任何事&quot;</td><td style="text-align:left;"><strong>垂直场景的专用 Agent</strong>（如科研文献整理、代码 Review）</td></tr><tr><td style="text-align:left;">&quot;零代码构建复杂系统&quot;</td><td style="text-align:left;"><strong>工程化的工作流编排</strong>（如 CI/CD 自动化、审批流水线）</td></tr><tr><td style="text-align:left;">&quot;AI 自主决策取代人类&quot;</td><td style="text-align:left;"><strong>人机协作的决策辅助</strong>（人负责判断，AI 负责执行和草稿）</td></tr><tr><td style="text-align:left;">&quot;新范式革命&quot;</td><td style="text-align:left;"><strong>模型能力提升带来的渐进式改进</strong></td></tr></tbody></table><p>真正创造价值的项目，有几个共同特征：</p><ol><li><strong>敢展示真实数据</strong>：用户日活、任务成功率、客户续费率</li><li><strong>解决具体问题</strong>：不是&quot;颠覆行业&quot;，而是&quot;帮生物学家省 30% 的文献整理时间&quot;</li><li><strong>人在环中（Human-in-the-loop）</strong>：保留人类最终决策权，而不是盲目追求&quot;全自动&quot;</li></ol><hr><h2 id="七、给开发者的生存指南" tabindex="-1">七、给开发者的生存指南 <a class="header-anchor" href="#七、给开发者的生存指南" aria-label="Permalink to &quot;七、给开发者的生存指南&quot;">​</a></h2><h3 id="不要做的事情" tabindex="-1">不要做的事情 <a class="header-anchor" href="#不要做的事情" aria-label="Permalink to &quot;不要做的事情&quot;">​</a></h3><ul><li>❌ 追着新概念跑，每三个月重构一次技术栈</li><li>❌ 把&quot;封装了 OpenAI API&quot;当成技术壁垒</li><li>❌ 在 PPT 里写&quot;AI 原生&quot;&quot;范式跃迁&quot;&quot;颠覆性创新&quot;</li><li>❌ 相信&quot;通用 Agent&quot;的叙事，忽视垂直场景的深耕</li></ul><h3 id="应该做的事情" tabindex="-1">应该做的事情 <a class="header-anchor" href="#应该做的事情" aria-label="Permalink to &quot;应该做的事情&quot;">​</a></h3><ul><li>✅ 关注<strong>模型能力的真实边界</strong>，而不是营销参数</li><li>✅ 把 Agent 当成<strong>自动化脚本的增强版</strong>，而不是魔法</li><li>✅ 在<strong>具体业务场景</strong>中验证价值，用数据说话</li><li>✅ 保持<strong>工程化思维</strong>：可观测、可回滚、有兜底</li></ul><hr><h2 id="八、总结" tabindex="-1">八、总结 <a class="header-anchor" href="#八、总结" aria-label="Permalink to &quot;八、总结&quot;">​</a></h2><p>AI Agent 圈的造词运动，本质是一场<strong>多方合谋的概念游戏</strong>：</p><ul><li>资本需要新叙事来维持估值</li><li>创业公司需要护城河幻觉来融资</li><li>自媒体需要焦虑流量来变现</li><li>从业者需要&quot;掌握最新范式&quot;的安全感</li></ul><p>四方合力，把同一个 <code>while</code> 循环包装成了四代&quot;革命性工程范式&quot;。</p><p>但技术不会骗人。Gartner 曲线正在爬坡，泡沫信号已经显现。当 2027 年&quot;Agent 已死&quot;的论调开始出现时，真正活下来的，不会是那些最会造词的公司，而是那些<strong>最懂业务、最能落地、最尊重工程常识</strong>的团队。</p><blockquote><p>概念会过时，循环会停止，但代码还在跑——只要它能跑通。</p></blockquote>`,76)])])}const q=e(i,[["render",o]]);export{u as __pageData,q as default};
